/** Own the listener and Vite resources for one dev shell run. */
const SHUTDOWN_GRACE_MS = 1500;
export class DevShellRun {
    beforeCleanup;
    resources = [];
    shuttingDown = false;
    constructor(beforeCleanup) {
        this.beforeCleanup = beforeCleanup;
    }
    get closing() {
        return this.shuttingDown;
    }
    addResource(resource) {
        if (this.closing) {
            void closeResource(resource);
            return;
        }
        this.resources.push(resource);
    }
    shutdown(signal) {
        if (signal === "exit") {
            const alreadyClosing = this.closing;
            this.shuttingDown = true;
            if (!alreadyClosing) {
                void closeResource(this.beforeCleanup);
            }
            // Exit handlers cannot await promises. Start all remaining cleanup,
            // including file removal when an earlier async cleanup timed out.
            for (let resource = this.resources.pop(); resource; resource = this.resources.pop()) {
                void closeResource(resource);
            }
            return;
        }
        if (this.closing) {
            process.exit(process.exitCode ?? 130);
            return;
        }
        this.shuttingDown = true;
        console.log("\n\x1b[2mShutting down...\x1b[0m");
        void this.finishShutdown();
    }
    async finishShutdown() {
        const timeout = setTimeout(() => {
            process.exit(process.exitCode ?? 130);
        }, SHUTDOWN_GRACE_MS);
        await closeResource(this.beforeCleanup);
        for (let resource = this.resources.pop(); resource; resource = this.resources.pop()) {
            await closeResource(resource);
        }
        clearTimeout(timeout);
        process.exit(process.exitCode ?? 0);
    }
}
async function closeResource(resource) {
    try {
        await resource();
    }
    catch (error) {
        console.error("Dev shell cleanup failed:", error);
    }
}
export function installProcessSignalHandlers(run) {
    for (const signal of ["SIGINT", "SIGTERM", "SIGHUP"]) {
        process.on(signal, () => run.shutdown(signal));
    }
    process.on("exit", () => run.shutdown("exit"));
    process.on("uncaughtException", error => {
        console.error(error);
        process.exitCode = 1;
        run.shutdown("SIGTERM");
    });
}
